var (
	// This bytecode and ABI is for a contract, which wraps the LibZip library for easier fuzz testing.
	// The source of this contract is here: https://github.com/danyalprout/fastlz/blob/main/src/FastLz.sol#L6-L10
	fastLzContract = &bind.MetaData{
		ABI: "[{\"type\":\"function\",\"name\":\"fastLz\",\"inputs\":[{\"name\":\"_data\",\"type\":\"bytes\",\"internalType\":\"bytes\"}],\"outputs\":[{\"name\":\"\",\"type\":\"uint256\",\"internalType\":\"uint256\"}],\"stateMutability\":\"pure\"}]",
	}

	fastLzBytecode = ""

	seeds = [][]byte{
		// https://basescan.org/tx/0x5dadeb52979f29fc7a7494c43fdabc5be1d8ff404f3aafe93d729fa8e5d00769
		common.FromHex(""),
		// https://basescan.org/tx/0xfaada76a2dac09fc17f5a28d066aaabefc6d82ef6589b211ed8c9f766b070721
		common.FromHex("b87602f873822105528304320f8409cfe5c98252089480c67432656d59144ceff962e8faf8926599bcf888011dfe52d06b633f80c001a08632f069f837aea7a28bab0affee14dda116956bd5a850a355c045d25afedd17a0084b8f273efffe17ece527116053e5781a4915ff89ab9c379f1e62c25b697687"),
		// https://basescan.org/tx/0x112864e9b971af6a1dac840018833c5a5a659acc187cfdaba919ad1da013678d
		common.FromHex(""),
		// https://basescan.org/tx/0x6905051352691641888d0c427fb137c5b95afb5870d5169ff014eff1d0952195
		common.FromHex("b87202f86f8221058303dc6c8310db1f84068fa8d7838954409436af2ff952a7355c8045fcd5e88bc9f6c8257f7b8080c001a0b89e7ff3d7694109e73e7f4244e032581670313c36e48e485c9c94b853bd81d2a038ffaf8f10859ce21d1f7f7046c3d08027fb8aa15b69038f6102be97aaa1179a"),
		// https://basescan.org/tx/0x6a38e9a26d7202a2268de69d2d47531c1a9829867579a483fb48d78e9e0b080d
		common.FromHex(""),
	}
)

// fastLzAddr is where FuzzFastLzSolidity deploys the LibZip wrapper contract.
var fastLzAddr = common.HexToAddress("0xfa57000000000000000000000000000000000001")

// fjordL1FeeParams are the L1 fee parameters FuzzFjordCostFunction writes into the L1Block
// predeploy. Both blob terms are nonzero, so the comparison covers the blob component of the fee.
var fjordL1FeeParams = opfees.L1FeeParams{
	L1BaseFee:     big.NewInt(12_345_678_901),
	L1BlobBaseFee: big.NewInt(987_654_321),
	BaseFeeScalar: big.NewInt(1_368),
	BlobFeeScalar: big.NewInt(810_949),
}

// FuzzFjordCostFunction checks that opfees.L1CostFjord agrees with the Fjord GasPriceOracle
// predeploy. The GasPriceOracle and L1Block code comes from the forge artifacts, and their storage
// is set in the genesis alloc at the slots the artifacts' storage layouts name.
func FuzzFjordCostFunction(f *testing.F) {
	for _, seed := range seeds {
		f.Add(seed)
	}

	artifacts := foundry.OpenArtifactsDir("../../packages/contracts-bedrock/forge-artifacts")
	gpoArtifact, err := artifacts.ReadArtifact("GasPriceOracle.sol", "GasPriceOracle")
	require.NoError(f, err)
	l1BlockArtifact, err := artifacts.ReadArtifact("L1Block.sol", "L1Block")
	require.NoError(f, err)

	gpoStorage := make(map[common.Hash]common.Hash)
	setStorageVar(f, gpoStorage, &gpoArtifact.StorageLayout, "isEcotone", []byte{1})
	setStorageVar(f, gpoStorage, &gpoArtifact.StorageLayout, "isFjord", []byte{1})

	l1BlockStorage := make(map[common.Hash]common.Hash)
	setStorageVar(f, l1BlockStorage, &l1BlockArtifact.StorageLayout, "basefee", fjordL1FeeParams.L1BaseFee.Bytes())
	setStorageVar(f, l1BlockStorage, &l1BlockArtifact.StorageLayout, "blobBaseFee", fjordL1FeeParams.L1BlobBaseFee.Bytes())
	setStorageVar(f, l1BlockStorage, &l1BlockArtifact.StorageLayout, "baseFeeScalar", fjordL1FeeParams.BaseFeeScalar.Bytes())
	setStorageVar(f, l1BlockStorage, &l1BlockArtifact.StorageLayout, "blobBaseFeeScalar", fjordL1FeeParams.BlobFeeScalar.Bytes())

	backend := simulated.NewBackend(types.GenesisAlloc{
		predeploys.GasPriceOracleAddr: {Code: gpoArtifact.DeployedBytecode.Object, Storage: gpoStorage},
		predeploys.L1BlockAddr:        {Code: l1BlockArtifact.DeployedBytecode.Object, Storage: l1BlockStorage},
	})
	defer func() {
		require.NoError(f, backend.Close())
	}()

	gpo, err := bindings.NewGasPriceOracleCaller(predeploys.GasPriceOracleAddr, backend.Client())
	require.NoError(f, err)

	// Read the parameters back through the predeploys, so a storage packing mistake fails here
	// rather than as a fee mismatch.
	opts := &bind.CallOpts{Context: f.Context()}
	isFjord, err := gpo.IsFjord(opts)
	require.NoError(f, err)
	require.True(f, isFjord)
	l1BaseFee, err := gpo.L1BaseFee(opts)
	require.NoError(f, err)
	require.Equal(f, fjordL1FeeParams.L1BaseFee.String(), l1BaseFee.String())
	blobBaseFee, err := gpo.BlobBaseFee(opts)
	require.NoError(f, err)
	require.Equal(f, fjordL1FeeParams.L1BlobBaseFee.String(), blobBaseFee.String())
	baseFeeScalar, err := gpo.BaseFeeScalar(opts)
	require.NoError(f, err)
	require.Equal(f, bigs.Uint64Strict(fjordL1FeeParams.BaseFeeScalar), uint64(baseFeeScalar))
	blobBaseFeeScalar, err := gpo.BlobBaseFeeScalar(opts)
	require.NoError(f, err)
	require.Equal(f, bigs.Uint64Strict(fjordL1FeeParams.BlobFeeScalar), uint64(blobBaseFeeScalar))

	f.Fuzz(func(t *testing.T, data []byte) {
		l1FeeSolidity, err := gpo.GetL1Fee(&bind.CallOpts{Context: t.Context()}, data)
		require.NoError(t, err)

		// GetL1Fee prices unsigned tx data: it adds 68 bytes to the FastLZ size for the signature.
		costData := opfees.NewRollupCostData(data)
		costData.FastLzSize += 68
		require.Equal(t, opfees.L1CostFjord(costData, fjordL1FeeParams).String(), l1FeeSolidity.String(), "data: %x", data)
	})
}

// setStorageVar writes value into the storage slot of the state variable label, at the variable's
// offset within the slot, as solc packs it.
func setStorageVar(t testing.TB, storage map[common.Hash]common.Hash, layout *solc.StorageLayout, label string, value []byte) {
	entry, err := layout.GetStorageLayoutEntry(label)
	require.NoError(t, err)
	varType, err := layout.GetStorageLayoutType(entry.Type)
	require.NoError(t, err)
	require.LessOrEqual(t, len(value), int(varType.NumberOfBytes), "value too large for %s", label)

	slot := common.BigToHash(new(big.Int).SetUint64(uint64(entry.Slot)))
	word := storage[slot]
	end := common.HashLength - int(entry.Offset)
	copy(word[end-len(value):end], value)
	storage[slot] = word
}

// FuzzFastLzSolidity checks that opfees.FlzCompressLen agrees with Solady's LibZip.
func FuzzFastLzSolidity(f *testing.F) {
	for _, seed := range seeds {
		f.Add(seed)
	}

	contractAbi, err := fastLzContract.GetAbi()
	require.NoError(f, err)

	backend := simulated.NewBackend(types.GenesisAlloc{
		fastLzAddr: {Code: common.FromHex(fastLzBytecode)},
	})
	defer func() {
		require.NoError(f, backend.Close())
	}()

	client := backend.Client()

	f.Fuzz(func(t *testing.T, data []byte) {
		req, err := contractAbi.Pack("fastLz", data)
		require.NoError(t, err)

		response, err := client.CallContract(t.Context(), ethereum.CallMsg{
			To:   &fastLzAddr,
			Data: req,
		}, nil)
		require.NoError(t, err)

		result, err := contractAbi.Unpack("fastLz", response)
		require.NoError(t, err)

		require.Equal(t, uint64(opfees.FlzCompressLen(data)), bigs.Uint64Strict(result[0].(*big.Int)))
	})
}

// FuzzFastLzCgo checks that opfees.FlzCompressLen agrees with the C FastLZ implementation.
func FuzzFastLzCgo(f *testing.F) {
	for _, seed := range seeds {
		f.Add(seed)
	}

	f.Fuzz(func(t *testing.T, data []byte) {
		if len(data) == 0 {
			t.Skip()
		}

		out, err := fastlz.Compress(data)
		require.NoError(t, err)
		require.Equal(t, len(out), int(opfees.FlzCompressLen(data)))
	})
}
